typedef float rational_t;
typedef unsigned long long uint64;
#define assert(x) ((void)0)

class pstring
{
  private:
    uint64 pchunk[4];

  public:
    bool operator == (const pstring &check_me) const
    {
      for (unsigned i=0; i<4; ++i)
      {
        if (pchunk[i] != check_me.pchunk[i])
          return false;
      }
      return true;
    }
};

template <class type>
class basic_attribute
{
  private:
    static pstring type_name;
    type value;

  public:
    virtual ~basic_attribute() {}
    const type &get () const
    {
      return value;
    }
};

template <class type>
class bounded_attribute
{
  private:
    static pstring type_name;
    type max_value;
    type min_value;
    type value;

  public:
    virtual ~bounded_attribute() {}
    const type &get () const
    {
      return value;
    }
};

class team_attrib : public basic_attribute<int>
{
  protected:
    static pstring attribute_name;

  public:
    const pstring &get_name() const { return attribute_name; }
};

class ammo_points_attrib : public bounded_attribute<int>
{
  protected:
    static pstring attribute_name;

  public:
    const pstring &get_name() const { return attribute_name; }
};

class ammo_clips_attrib : public bounded_attribute<int>
{
  protected:
    static pstring attribute_name;

  public:
    const pstring &get_name() const { return attribute_name; }
};

class entity_interface
{
  protected:
    void *my_entity;

  public:
    virtual ~entity_interface() {}
};

class soft_attrib_interface : public entity_interface
{
  protected:
    team_attrib team;
};

class character_soft_attrib_interface : public soft_attrib_interface
{
  private:
    ammo_points_attrib ammo_points;
    ammo_clips_attrib ammo_clips;

  public:
    virtual const rational_t get_soft_attrib_num(pstring &by_name) const 
    {
      #define PROCESS_NUMBERS_ONLY
      #define MAC(atype, itype, itype_name, code_name, str_name, default_val, min_val, max_val) \
        if (by_name == code_name##.get_name()) { return (rational_t)##code_name##.get(); }

      MAC( basic, int, "INT", team, "TEAM", 0x00000100, -1, -1 )
      MAC( bounded, int, "INT", ammo_points, "AMMO_POINTS", 100, 0, 100 )
      MAC( bounded, int, "INT", ammo_clips, "AMMO_CLIPS", 1, 0, 10 )
      #undef MAC
      #undef PROCESS_NUMBERS_ONLY
      assert("Could not get a character soft attribute number by name." == 0);
      return 0.0f;
    }
};
